SELECT ord,note FROM order_slice WHERE shop='shared-store-1234567890-A' ORDER BY ord ASC NULLS FIRST LIMIT 3 OFFSET 1;
SELECT ord,note FROM order_slice WHERE shop='shared-store-1234567890-A' ORDER BY ord DESC NULLS LAST LIMIT 3 OFFSET 1;
