BEGIN;
SAVEPOINT before_change;
UPDATE order_slice SET ord=-100 WHERE shop='shared-store-1234567890-A' AND ord=3;
SELECT ord,note FROM order_slice WHERE shop='shared-store-1234567890-A' ORDER BY ord LIMIT 3;
ROLLBACK TO before_change;
SELECT ord,note FROM order_slice WHERE shop='shared-store-1234567890-A' ORDER BY ord LIMIT 3;
COMMIT;
REINDEX TABLE order_slice;
SELECT ord,note FROM order_slice WHERE shop='shared-store-1234567890-A' AND ord>=-1 ORDER BY ord DESC LIMIT 2;
